ana\",{\"href\":\"/en/search/synonyms/?original=janārdana\",\"children\":[\"$\",\"em\",null,{\"children\":\"janārdana\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"O Kṛṣṇa\"}}],\".\"]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a34054a12ab9f501'',t:''MTc4ODIyNDM0OA==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.body.appendChild(a);if(''loading''!==document.readyState)c();else if(window.addEventListener)document.addEventListener(''DOMContentLoaded'',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);''loading''!==document.readyState&&(document.onreadystatechange=e,c())}}}})();', 'https://vedabase.io/en/library/bg/1/37-38/', true),
(1, '39', 39, 'class="av-devanagari">कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः ।
धर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत ॥ ३९ ॥

<div', 'class="av-verse_text">kula-kṣaye praṇaśyanti
kula-dharmāḥ sanātanāḥ
dharme naṣṭe kulaṁ kṛtsnam
adharmo ’bhibhavaty uta

<div', 'class="av-synonyms">kula-kṣaye — in destroying the family; praṇaśyanti — become vanquished; kula-dharmāḥ — the family traditions; sanātanāḥ — eternal; dharme — religion; naṣṭe — being destroyed; kulam — family; kṛtsnam — whole; adharmaḥ — irreligion; abhibhavati — transforms; uta — it is said.

<div', 'class="av-translation">With the destruction of the dynasty, the eternal family tradition is vanquished, and thus the rest of the family becomes involved in irreligion.

<div', 'class="av-purport">In the system of the varṇāśrama institution there are many principles of religious traditions to help members of the family grow properly and attain spiritual values. The elder members are responsible for such purifying processes in the family, beginning from birth to death. But on the death of the elder members, such family traditions of purification may stop, and the remaining younger family members may develop irreligious habits and thereby lose their chance for spiritual salvation. Therefore, for no purpose should the elder members of the family be slain.

TEXTS 37-38TEXT 40

